      display: flex;
      flex-direction: column;
      overflow: hidden;
    }

    /* ==========================================================================
       ESTILOS INTERNOS DAS TELAS LO-FI (UNOORIA & UNOORIAA)
       Estritamente 9 tokens de cor em cinza.
       ========================================================================== */
    .app-screen {
      flex: 1;
      display: flex;
      flex-direction: column;
      height: 100%;
      background-color: var(--superficie-base);
      overflow-y: auto;
      overflow-x: hidden;
      position: relative;
    }

    /* Chrome institucional Unooria */
    .topbar-unooria {
      height: 48px;
      border-bottom: 1px solid var(--borda-padrao);
      background-color: var(--superficie-elevada);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 12px;
      font-size: 12px;
      font-weight: 700;
      flex-shrink: 0;
    }

    .cracha-auditor {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 11px;
      padding: 4px 8px;
      background-color: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      border-radius: 4px;
    }

    /* Stepper Unooria */
    .stepper-header {
      padding: 10px 14px;
      border-bottom: 1px solid var(--borda-padrao);
      background-color: var(--superficie-base);
      display: flex;
      flex-direction: column;
      gap: 4px;
      flex-shrink: 0;
    }

    .stepper-passo {
      font-size: 11px;
      font-weight: 700;
      color: var(--texto-secundario);
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .stepper-instrucao {
      font-size: 13px;
      font-weight: 600;
      color: var(--texto-primario);
      line-height: 1.35;
    }

    /* Chrome UnooriaAI (Chat Assistant) */
    .topbar-unooriaai {
      height: 44px;
      border-bottom: 1px solid var(--borda-padrao);
      background-color: var(--superficie-base);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 12px;
      font-size: 12px;
      font-weight: 700;
      flex-shrink: 0;
    }

    .abas-perfis {
      display: flex;
      border-bottom: 1px solid var(--borda-padrao);
      background-color: var(--superficie-elevada);
      flex-shrink: 0;
    }

    .aba-perfil {
      flex: 1;
      padding: 8px 4px;
      text-align: center;
      font-size: 12px;
      font-weight: 600;
      color: var(--texto-secundario);
      border-bottom: 2px solid transparent;
      cursor: pointer;
    }

    .aba-perfil.ativa {
      color: var(--texto-primario);
      border-bottom-color: var(--borda-foco);
      background-color: var(--superficie-base);
    }

    /* Área de Conteúdo da Tela */
    .screen-content {
      flex: 1;
      padding: 14px;
      display: flex;
      flex-direction: column;
      gap: 12px;
      overflow-y: auto;
    }

    /* Rodapé da tela (botão de ação) */
    .screen-footer {
      padding: 12px 14px;
      border-top: 1px solid var(--borda-padrao);
      background-color: var(--superficie-base);
      flex-shrink: 0;
      display: flex;
      flex-direction: column;
      gap: 6px;
    }

    .anotacao-estado {
      font-size: 10px;
      color: var(--texto-secundario);
      text-align: center;
      font-family: monospace;
      margin-top: 4px;
    }

    /* Componentes Gerais DS Lo-Fi */
    .card-lofi {
      background-color: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      border-radius: 8px;
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .card-lofi.foco {
      border: 2px solid var(--borda-foco);
    }

    .btn-lofi {
      width: 100%;
      min-height: 44px;
      border-radius: 6px;
      border: 1px solid var(--borda-foco);
      background-color: var(--acao-primaria);
      color: var(--superficie-base);
      font-size: 13px;
      font-weight: 700;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      text-align: center;
      padding: 8px 12px;
    }

    .btn-lofi.secundario {
      background-color: var(--acao-secundaria);
      color: var(--texto-primario);
      border-color: var(--borda-padrao);
    }

    .btn-lofi:disabled {
      background-color: var(--acao-secundaria);
      color: var(--texto-secundario);
      border-color: var(--borda-padrao);
      cursor: not-allowed;
      opacity: 0.6;
    }

    .btn-audio-lofi {
      width: 64px;
      height: 64px;
      border-radius: 50%;
      border: 2px solid var(--borda-padrao);
      background-color: var(--superficie-elevada);
      color: var(--texto-primario);
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 12px;
      cursor: pointer;
      margin: 0 auto;
    }

    .radio-opcao {
      display: flex;
      align-items: flex-start;
      gap: 10px;
      padding: 10px;
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      background-color: var(--superficie-base);
      cursor: pointer;
      font-size: 12px;
      line-height: 1.35;
    }

    .radio-opcao.selecionada {
      border: 2px solid var(--borda-foco);
      background-color: var(--superficie-elevada);
      font-weight: 600;
    }

    .radio-circle {
      width: 18px;
      height: 18px;
      border-radius: 50%;
      border: 2px solid var(--borda-padrao);
      flex-shrink: 0;
      margin-top: 1px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .radio-opcao.selecionada .radio-circle {
      border-color: var(--borda-foco);
    }

    .radio-opcao.selecionada .radio-circle::after {
      content: "";
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background-color: var(--borda-foco);
    }

    .chat-bubble {
      max-width: 85%;
      padding: 10px 12px;
      border-radius: 8px;
      font-size: 12px;
      line-height: 1.4;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .chat-bubble.aluno {
      align-self: flex-end;
      background-color: var(--acao-secundaria);
      border: 1px solid var(--borda-padrao);
    }

    .chat-bubble.assistente {
      align-self: flex-start;
      background-color: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
    }

    .chat-meta {
      font-size: 10px;
      color: var(--texto-secundario);
      display: flex;
      gap: 6px;
      align-items: center;
    }

    .alerta-corte {
      border: 2px solid var(--borda-foco);
      background-color: var(--superficie-base);
      padding: 8px 10px;
      border-radius: 6px;
      font-size: 12px;
      font-weight: 700;
      color: var(--texto-primario);
      margin-top: 6px;
    }

    .prompt-readonly {
      height: 44px;
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      background-color: var(--superficie-elevada);
      padding: 0 12px;
      display: flex;
      align-items: center;
      font-size: 12px;
      color: var(--texto-secundario);
      font-style: italic;
    }

    /* Modais e Overlays */
    .modal-overlay {
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background-color: rgba(0,0,0,0.4);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 16px;
      z-index: 50;
    }

    .modal-caixa {
      background-color: var(--superficie-base);
      border: 2px solid var(--borda-foco);
      border-radius: 8px;
      padding: 16px;
      width: 100%;
      max-width: 320px;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .bottom-sheet {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      height: 80%;
      background-color: var(--superficie-base);
      border-top: 3px solid var(--borda-foco);
      border-radius: 16px 16px 0 0;
      box-shadow: 0 -8px 24px rgba(0,0,0,0.2);
      display: flex;
      flex-direction: column;
      z-index: 40;
    }

    .sheet-alca {
      width: 40px;
      height: 4px;
      background-color: var(--borda-padrao);
      border-radius: 2px;
      margin: 8px auto 4px auto;
    }

    /* Colunas de classificação na E5 */
    .coluna-drop {
      border: 2px dashed var(--borda-padrao);
      border-radius: 6px;
      padding: 10px;
      min-height: 110px;
      background-color: var(--superficie-elevada);
      display: flex;
      flex-direction: column;
      gap: 6px;
    }

    .coluna-drop.ativa {
      border-color: var(--borda-foco);
      border-style: solid;
    }

    .puzzle-card {
      padding: 8px 10px;
      background-color: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      border-radius: 4px;
      font-size: 11px;
      cursor: pointer;
    }

    .puzzle-card.selecionado {
      border: 2px solid var(--borda-foco);
      background-color: var(--acao-secundaria);
      font-weight: 700;
    }

    /* Concessão da Demo Banner */
    .concessao-demo {
      font-size: 10px;
      padding: 4px 6px;
      background-color: var(--acao-secundaria);
      border: 1px dashed var(--borda-padrao);
      color: var(--texto-secundario);
      text-align: center;
      border-radius: 3px;
    }
  </style>
</head>
