      badgesContainer.innerHTML += `<span class="badge-marca">${screenId} · ${estado}</span>`;

      // Atualiza painel pedagógico (One-pager literal)
      document.getElementById('painel-etapa-tag').textContent = prefixoEtapa.startsWith('E') ? `Etapa ${prefixoEtapa.substring(1)}` : 'Sistema';
      document.getElementById('painel-etapa-titulo').textContent = dadosEtapa.nome;
      document.getElementById('painel-etapa-desc').textContent = dadosEtapa.desc;
      document.getElementById('painel-etapa-mecanismo').textContent = dadosEtapa.mecanismo;
      document.getElementById('painel-fonte').textContent = `Fonte: ${dadosEtapa.fonte}`;

      // Atualiza rodapé
      document.getElementById('rodape-tela-id').textContent = `${screenId} (${estado})`;
      document.getElementById('rodape-acao').textContent = dadosRodape.acao;
      document.getElementById('rodape-muda').textContent = dadosRodape.muda;
    }

    function navegarRelativo(delta) {
      exibirTela(indiceAtual + delta);
    }

    function irParaTela(screenId, estado) {
      const idx = quadros.findIndex(q => 
        q.getAttribute('data-screen-id') === screenId && 
        q.getAttribute('data-estado') === estado
      );
      if (idx !== -1) {
        exibirTela(idx);
      }
    }

    function lidarTeclado(e) {
      if (e.key === 'ArrowRight' || e.key === 'PageDown') {
        navegarRelativo(1);
      } else if (e.key === 'ArrowLeft' || e.key === 'PageUp') {
        navegarRelativo(-1);
      }
    }

    window.addEventListener('DOMContentLoaded', init);
